"""목요일 교보재. python teacher_demo.py → http://127.0.0.1:8765"""
import argparse
import asyncio
import contextlib
from collections import deque
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import base64
import zlib
import threading
import time
import webbrowser

from device_server import DeviceServers
from device_client import request_async, request_sync, wait_output_async, wait_output_sync

CASES = {"single": "단일 장치", "blocking": "블로킹 순차", "sequential": "비동기 순차",
         "concurrent": "Task 동시", "silent": "A 무응답"}


class Demo:
    def __init__(self, devices):
        self.devices = devices
        self.lock = threading.RLock()
        self.thread = None
        self.reset()

    def reset(self):
        with self.lock:
            if getattr(self, "running", False):
                return False
            self.running = False
            self.case = "준비"
            self.started = time.monotonic()
            self.finished = self.started
            self.events = deque(maxlen=160)
            self.ticks = deque(maxlen=400)
            self.observed = {name: {"output": None, "busy": None, "last_ok": None, "error": None}
                             for name in ("A", "B")}
            self.result = None
            for device in self.devices.devices:
                device.reset()
            return True

    def stamp(self):
        return time.monotonic() - self.started

    def event(self, name, message):
        with self.lock:
            self.events.append({"time": round(self.stamp(), 3), "name": name, "message": message})

    def observe(self, name, reply=None, error=None):
        with self.lock:
            item = self.observed[name]
            if reply is not None:
                item.update(output=reply["output"], busy=reply["busy"], last_ok=self.stamp(), error=None)
            else:
                item["error"] = str(error)

    def snapshot(self):
        now = time.monotonic()
        with self.lock:
            elapsed = (self.finished or now) - self.started
            data = {"running": self.running, "case": self.case, "elapsed": round(elapsed, 3),
                    "events": list(self.events), "ticks": list(self.ticks),
                    "observed": {name: dict(value) for name, value in self.observed.items()},
                    "result": self.result}
            data["heartbeat_age"] = round(max(0, elapsed - self.ticks[-1]), 2) if self.ticks else None
            for value in data["observed"].values():
                value["age"] = None if value["last_ok"] is None else round(max(0, elapsed-value["last_ok"]), 2)
        data["devices"] = [d.snapshot() for d in self.devices.devices]
        return data

    def set_a_mode(self, mode):
        with self.lock:
            if self.running:
                return False
            self.devices.devices[0].set_mode(mode)
            return True

    def start(self, case):
        if case not in CASES:
            raise ValueError("시연 이름 오류")
        with self.lock:
            if not self.reset():
                return False
            self.running = True
            self.case = CASES[case]
            self.started = time.monotonic()
            self.finished = None
        self.thread = threading.Thread(target=self._run, args=(case,), daemon=True)
        self.thread.start()
        return True

    def _run(self, case):
        try:
            asyncio.run(self.scenario(case))
        except Exception as error:
            self.event("오류", f"{type(error).__name__}: {error}")
            with self.lock:
                self.result = "시연 오류 — 터미널과 기록 확인"
        finally:
            with self.lock:
                self.running = False
                self.finished = time.monotonic()

    async def scenario(self, case):
        ports = self.devices.ports

        async def heartbeat():
            while True:
                with self.lock:
                    self.ticks.append(round(self.stamp(), 3))
                await asyncio.sleep(0.1)

        async def monitor(name, port):
            previous_error = None
            while True:
                try:
                    reply = await request_async(port, "status", timeout=0.7)
                    self.observe(name, reply=reply)
                    if previous_error:
                        self.event(name, "상태 조회 복구")
                    previous_error = None
                except (TimeoutError, ConnectionError, ValueError) as error:
                    self.observe(name, error=error)
                    if type(error).__name__ != previous_error:
                        self.event(name, f"상태 조회 {type(error).__name__}")
                    previous_error = type(error).__name__
                await asyncio.sleep(0.2)

        async def work(name, port, blocking=False):
            self.event(name, "켜기 요청")
            try:
                if blocking:
                    request_sync(port, "on")
                    self.event(name, "접수 — 완료 대기")
                    reply = wait_output_sync(port)
                else:
                    await request_async(port, "on")
                    self.event(name, "접수 — 완료 대기")
                    reply = await wait_output_async(port)
                self.event(name, "출력 켜짐 확인")
                return {"device": name, "ok": True, "output": reply["output"]}
            except (TimeoutError, ConnectionError, ValueError) as error:
                self.event(name, f"작업 실패: {type(error).__name__}")
                return {"device": name, "ok": False, "error": type(error).__name__}

        monitoring = [asyncio.create_task(heartbeat())]
        monitoring += [asyncio.create_task(monitor(name, port)) for name, port in zip(("A", "B"), ports)]
        try:
            await asyncio.sleep(0.08)  # 시작 상태를 한 번 관측한 뒤 비교한다.
            if case == "silent":
                self.devices.devices[0].set_mode("silent")
                self.event("A", "모의 장치 무응답 시작")
            if case == "single":
                result = [await work("A", ports[0])]
            elif case in ("blocking", "sequential"):
                result = []
                result.append(await work("A", ports[0], blocking=case == "blocking"))
                result.append(await work("B", ports[1], blocking=case == "blocking"))
            else:
                task_a = asyncio.create_task(work("A", ports[0]))
                task_b = asyncio.create_task(work("B", ports[1]))
                result = [await task_a, await task_b]
            self.event("PC", "작업 종료 — 마지막 상태 확인")
            await asyncio.sleep(0.25)
            with self.lock:
                self.result = result
        finally:
            for task in monitoring:
                task.cancel()
            await asyncio.gather(*monitoring, return_exceptions=True)


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass

    def send(self, code, body, content_type="application/json; charset=utf-8"):
        payload = body if isinstance(body, bytes) else json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        with contextlib.suppress(BrokenPipeError, ConnectionResetError):
            self.wfile.write(payload)

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path == "/api/state":
            self.send(200, self.server.demo.snapshot())
        elif path in ("/", "/index.html"):
            self.send(200, _ASSETS["dashboard.html"], "text/html; charset=utf-8")
        elif path in ("/Pretendard-Regular.otf", "/FONT-LICENSE.txt"):
            self.send(200, _ASSETS[path[1:]], "font/otf" if path.endswith(".otf") else "text/plain; charset=utf-8")
        elif path == "/house-style.css":
            self.send(200, _ASSETS["house-style.css"], "text/css; charset=utf-8")
        else:
            self.send(404, {"error": "not found"})

    def do_POST(self):
        try:
            if self.headers.get("Content-Type", "").split(";")[0] != "application/json":
                raise ValueError("JSON 요청 필요")
            length = int(self.headers.get("Content-Length", 0))
            if not 0 < length <= 1024:
                raise ValueError("요청 길이 오류")
            request = json.loads(self.rfile.read(length))
            if not isinstance(request, dict):
                raise ValueError("객체 요청 필요")
            if self.path == "/api/run":
                ok = self.server.demo.start(request.get("case"))
            elif self.path == "/api/mode":
                ok = self.server.demo.set_a_mode(request.get("mode"))
            elif self.path == "/api/reset":
                ok = self.server.demo.reset()
            else:
                self.send(404, {"error": "not found"})
                return
            self.send(200 if ok else 409, {"ok": ok})
        except (ValueError, TypeError) as error:
            self.send(400, {"error": str(error)})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--no-browser", action="store_true")
    parser.add_argument("--port", type=int, default=8765)
    args = parser.parse_args()
    try:
        with DeviceServers() as devices:
            demo = Demo(devices)
            server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
            server.daemon_threads = True
            server.demo = demo
            url = f"http://127.0.0.1:{args.port}"
            print(f"교보재: {url}\n장치 A: 9101 / 장치 B: 9102\n종료: 이 터미널에서 Ctrl+C", flush=True)
            if not args.no_browser:
                webbrowser.open(url)
            try:
                server.serve_forever(poll_interval=0.1)
            except KeyboardInterrupt:
                print("\n종료합니다.")
            finally:
                server.server_close()
    except OSError as error:
        print(f"시작 실패: {error}\n이전에 실행한 교보재 터미널에서 Ctrl+C 후 다시 실행하세요.")
        raise SystemExit(1)


